//! Cross-language conformance.
//!
//! These vectors were generated by the Go implementation. If Rust and Go
//! ever disagree on encoding or hashing, this fails — which is the whole
//! point of `docs/04`'s shared reference vectors.

use risk_core::canonical;
use serde_json::Value;

fn vectors() -> Vec<Value> {
    let raw = include_str!("../../../../schemas/v1/canonical-vectors.json");
    let doc: Value = serde_json::from_str(raw).expect("vectors parse");
    doc["vectors"].as_array().expect("vector array").clone()
}

#[test]
fn rust_reproduces_go_encoding() {
    for v in vectors() {
        let name = v["name"].as_str().unwrap();
        let want = v["encoded"].as_str().unwrap();
        let got = canonical::encode(&v["value"]).unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert_eq!(
            String::from_utf8(got).unwrap(),
            want,
            "encoding mismatch for vector: {name}"
        );
    }
}

#[test]
fn rust_reproduces_go_hashes() {
    for v in vectors() {
        let name = v["name"].as_str().unwrap();
        let want = v["sha256"].as_str().unwrap();
        let got = canonical::hash_hex(&v["value"]).unwrap();
        assert_eq!(got, want, "hash mismatch for vector: {name}");
    }
}

/// Key order in the source document must not affect the output — that is
/// what makes a snapshot hash reproducible from re-serialized evidence.
#[test]
fn key_order_does_not_affect_hash() {
    let a: Value = serde_json::from_str(r#"{"b":1,"a":2,"c":3}"#).unwrap();
    let b: Value = serde_json::from_str(r#"{"c":3,"a":2,"b":1}"#).unwrap();
    assert_eq!(canonical::hash_hex(&a).unwrap(), canonical::hash_hex(&b).unwrap());
}

/// Arrays represent real sequences, so their order is meaningful and must
/// change the hash (`docs/04`).
#[test]
fn array_order_changes_hash() {
    let a: Value = serde_json::from_str(r#"{"e":[1,2,3]}"#).unwrap();
    let b: Value = serde_json::from_str(r#"{"e":[3,2,1]}"#).unwrap();
    assert_ne!(canonical::hash_hex(&a).unwrap(), canonical::hash_hex(&b).unwrap());
}

/// Floats have no canonical decimal form both languages agree on, and never
/// carry an authorization amount. Rejected rather than rounded.
#[test]
fn floats_are_rejected() {
    let v: Value = serde_json::from_str(r#"{"x":1.5}"#).unwrap();
    assert_eq!(canonical::encode(&v), Err(canonical::Error::Float));
}

/// A u128-scale integer must survive as written; rounding it through f64
/// would corrupt an amount.
#[test]
fn large_integers_survive_exactly() {
    let v: Value = serde_json::from_str(r#"{"amount":340282366920938463463374607431768211455}"#)
        .unwrap();
    let encoded = String::from_utf8(canonical::encode(&v).unwrap()).unwrap();
    assert!(encoded.contains("340282366920938463463374607431768211455"));
}
